pub struct SmallVec<T> {
    data: [T; 2],
    len: usize,
}

impl<T: Copy + Default> SmallVec<T> {
    pub fn new() -> Self {
        Self {
            data: [T::default(); 2],
            len: 0,
        }
    }

    pub fn push(&mut self, val: T) {
        if self.len < 2 {
            self.data[self.len] = val;
            self.len += 1;
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn insert_many(&mut self, index: usize, elements: &[T]) {
        if index > self.len {
            return;
        }
        let num_items = elements.len();
        let new_len = match self.len.checked_add(num_items) {
            Some(n) => n,
            None => return,
        };
        if new_len > self.data.len() {
            return;
        }
        let tail_len = self.len - index;
        for i in (0..tail_len).rev() {
            let src = index + i;
            let dst = index + num_items + i;
            if dst < self.data.len() && src < self.data.len() {
                self.data[dst] = self.data[src];
            } else {
                return;
            }
        }
        for (i, &elem) in elements.iter().enumerate() {
            if let Some(slot) = self.data.get_mut(index + i) {
                *slot = elem;
            } else {
                return;
            }
        }
        self.len = new_len;
    }

    pub fn get(&self, index: usize) -> Option<T> {
        if index < self.len {
            Some(self.data[index])
        } else {
            None
        }
    }
}

impl<T: Copy + Default> Default for SmallVec<T> {
    fn default() -> Self {
        Self::new()
    }
}

